export type Review = {
  rating: number;
  comment: string;
  reviewerName: string;
};

export type Product = {
  id: string;
  name: string;
  title: string;
  price: number;
  stock: number;
  category: string;
  thumbnail: string;
  description: string;
  reviews: Review[];
};

export type ProductDraft = {
  title: string;
  price: number;
  stock: number;
  category: string;
  thumbnail: string;
  description: string;
};

export type ProductList = {
  products: Product[];
  total: number;
};

export type SearchQuery = {
  q: string;
  limit: number;
  sortBy: (typeof SORT_FIELDS)[number];
};

